/**
 * templates-route.js — client-saas /templates
 *
 * A browse view for the starter flows. Until now /templates was one of the generic
 * SECTION_ROUTES placeholders, so the side-nav item and the dashboard both led to a
 * stub even though the gallery content already existed — it was only reachable from
 * the "Template" button inside the Magnets page.
 *
 * Deliberately NOT a second provisioning path. Choosing a template here parks the
 * choice via setPendingTemplate() and navigates to #/magnets, which claims it on
 * init and runs the one existing flow (owner picker → provisionDraft → applyTemplate
 * → open the edit modal). Duplicating that here would mean a second place to keep
 * correct, and it depends on magnets-route's loaded state anyway.
 *
 * Preview is the exception, and only because it provisions nothing: it renders the
 * template's own steps through the SAME openPreviewModal()/magnetToPackage() pair the
 * magnet card and flow builder use, so what you see before committing is what the
 * template actually builds.
 *
 * Cards come from templateCardHTML() — the same renderer the picker modal uses, so
 * the two views cannot describe a template differently.
 */

import AuthController from '../services/AuthController.js';
import { openPreviewModal, magnetToPackage } from './magnet-preview.js';
import {
  MAGNET_TEMPLATES,
  TEMPLATE_CATEGORIES,
  templateCardHTML,
  ensureTemplateStyles,
  setPendingTemplate,
} from './magnet-templates.js';

const ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ESC[c]);

// Starting a magnet is the same right the Magnets page gates its New/Template buttons
// on. A managed client whose reseller builds their magnets for them still gets the full
// browse + preview experience; only the commit action goes away.
const USE_CAPS = ['provision_magnets', 'manage_magnets'];
const canUseTemplates = () => AuthController.getCapabilities().some((c) => USE_CAPS.includes(c));

/** [category, count] for every category actually present, in TEMPLATE_CATEGORIES order. */
function categoryCounts() {
  const counts = new Map();
  for (const t of MAGNET_TEMPLATES) counts.set(t.category, (counts.get(t.category) || 0) + 1);
  return Object.keys(TEMPLATE_CATEGORIES)
    .filter((c) => counts.has(c))
    .map((c) => [c, counts.get(c)]);
}

const chipHTML = (cat, label, count, pressed) =>
  `<button class="m5t-chip--filter" type="button" data-cat="${esc(cat)}" aria-pressed="${pressed}">${esc(label)}<span class="m5t-chip__count">${count}</span></button>`;

let stylesInjected = false;

function ensureStyles() {
  ensureTemplateStyles(); // .mag-tpl-grid / .mag-tpl-card / gallery face / derived art
  if (stylesInjected) return;
  const style = document.createElement('style');
  style.id = 'm5t-templates-page-styles';
  style.textContent = `
    .page-shell[data-section="templates"] .tpl-filters { margin: 0 0 20px; }
    .page-shell[data-section="templates"] .settings-note { margin: 0 0 20px; }
  `;
  document.head.appendChild(style);
  stylesInjected = true;
}

export function render() {
  ensureStyles();
  const canUse = canUseTemplates();
  return `
    <div class="page-shell" data-section="templates">
      <div class="page-header">
        <div class="page-header-text">
          <h1 class="page-title">Templates</h1>
          <p class="page-description">Start from a proven flow instead of a blank magnet.</p>
        </div>
        <a class="btn btn-secondary" href="#/magnets">
          <span class="material-symbols-outlined" aria-hidden="true">bolt</span>
          Your magnets
        </a>
      </div>

      ${canUse ? '' : `<div class="settings-note" id="tpl-readonly-note">
        <span class="material-symbols-outlined" aria-hidden="true">lock</span>
        Setup managed by your provider.
      </div>`}

      <div class="m5t-chip-row tpl-filters" id="tpl-filters" role="group" aria-label="Filter templates by category">
        ${chipHTML('all', 'All', MAGNET_TEMPLATES.length, 'true')}
        ${categoryCounts().map(([cat, count]) => chipHTML(cat, TEMPLATE_CATEGORIES[cat], count, 'false')).join('')}
      </div>

      <div class="mag-tpl-grid mag-tpl-grid--page" id="tpl-grid">
        ${MAGNET_TEMPLATES.map((t) => templateCardHTML(t, { detail: true, gallery: true, canUse })).join('')}
      </div>
    </div>`;
}

export function init() {
  const grid = document.getElementById('tpl-grid');

  document.getElementById('tpl-filters')?.addEventListener('click', (e) => {
    const chip = e.target.closest('[data-cat]');
    if (!chip) return;
    // aria-pressed is the state, not a decoration: the chips are a single-choice
    // group, so exactly one is pressed and the cards follow it.
    chip.parentElement.querySelectorAll('[data-cat]').forEach((c) => {
      c.setAttribute('aria-pressed', String(c === chip));
    });
    const cat = chip.dataset.cat;
    grid?.querySelectorAll('.mag-tpl-card').forEach((card) => {
      card.hidden = !(cat === 'all' || card.dataset.cat === cat);
    });
  });

  grid?.addEventListener('click', (e) => {
    const preview = e.target.closest('[data-preview]');
    if (preview) {
      const t = MAGNET_TEMPLATES.find((x) => x.id === preview.dataset.preview);
      // Named after the template, so an unsaved-magnet preview and a template
      // preview are never confusable in the modal's own header line.
      if (t) openPreviewModal(() => magnetToPackage({ ...t.appearance, steps: t.steps, name: t.name }));
      return;
    }
    const btn = e.target.closest('[data-tpl]');
    if (!btn) return;
    setPendingTemplate(btn.dataset.tpl);
    // Hash assignment rather than router.navigate(): matches how the rest of the app
    // moves between sections (the nav and every view-all link are plain #/ hrefs).
    window.location.hash = '#/magnets';
  });
}

export default { render, init };
